/**
 * Validate bundle using Ajv 2020 compiled standalone validator.
 *
 * @param {unknown} bundle
 * @returns {Array<{ code: string, severity: string, message: string }>}
 */
export function validateCompiledCartonWorkflowSchema(bundle) {
  const valid = validate(bundle);
  if (valid) return [];

  const errors = validate.errors || [];
  return errors.map((err) => {
    let code = "SCHEMA_VALIDATION_ERROR";
    if (err.keyword === "additionalProperties") {
      code = "SCHEMA_ADDITIONAL_PROPERTY_FORBIDDEN";
    } else if (err.keyword === "required") {
      code = "SCHEMA_REQUIRED_PROPERTY_MISSING";
    } else if (err.keyword === "const") {
      code = "SCHEMA_CONST_MISMATCH";
      if (err.instancePath === "/source/producer") {
        code = "SCHEMA_PRODUCER_INVALID";
      }
    } else if (err.keyword === "enum") {
      code = "SCHEMA_ENUM_MISMATCH";
    } else if (err.keyword === "pattern") {
      code = "SCHEMA_PATTERN_MISMATCH";
    } else if (err.keyword === "type") {
      code = "SCHEMA_TYPE_MISMATCH";
    }

    const pathStr = err.instancePath ? err.instancePath.replace(/^\//, "").replace(/\//g, ".") : "root";
    const propName = err.params && err.params.additionalProperty ? ' "' + err.params.additionalProperty + '"' : '';
    return {
      code,
      severity: "ERROR",
      message: '[Schema ' + err.keyword + '] ' + pathStr + propName + ': ' + (err.message || 'schema constraint violated'),
    };
  });
}
